import type { VNode, VNodeChild } from '../vnode'
import {
  ARRAY_ITERATE_KEY,
  TrackOpTypes,
  reactive,
  track,
} from '@vue/reactivity'
import { warn } from '../warning'

/**
 * v-for string
 * @private
 */
export function renderList(
  source: string,
  renderItem: (value: string, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for number
 */
export function renderList(
  source: number,
  renderItem: (value: number, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for array
 */
export function renderList<T>(
  source: T[],
  renderItem: (value: T, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for iterable
 */
export function renderList<T>(
  source: Iterable<T>,
  renderItem: (value: T, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for object
 */
export function renderList<T>(
  source: T,
  renderItem: <K extends keyof T>(
    value: T[K],
    key: string,
    index: number,
  ) => VNodeChild,
): VNodeChild[]

/**
 * Actual implementation
 */
export function renderList(
  source: any,
  renderItem: (...args: any[]) => VNodeChild,
  cache?: any[],
  index?: number,
): VNodeChild[] {
  let ret: VNodeChild[]
  const cached = (cache && cache[index!]) as VNode[] | undefined
  let typeTag = ''
  if (source == null) {
    typeTag = ''
  } else {
    typeTag = Object.prototype.toString.call(source)
  }
  const sourceIsArray = Array.isArray(source)
  const sourceIsString = typeof source === 'string'
  const sourceIsNumber = typeof source === 'number'
  const sourceIsObject = source !== null && typeof source === 'object'
  const sourceIsWeakMap = typeTag === '[object WeakMap]'
  const sourceIsWeakSet = typeTag === '[object WeakSet]'

  if (sourceIsArray) {
    let sourceIsReactiveArray = false
    if (source) {
      if (source.__v_isReadonly) {
        let readonlyProbe: any = source.__v_raw
        while (readonlyProbe) {
          if (readonlyProbe.__v_isReadonly) {
            const nestedRaw = readonlyProbe.__v_raw
            if (nestedRaw) {
              readonlyProbe = nestedRaw
            } else {
              readonlyProbe = null
              break
            }
          } else {
            break
          }
        }
        if (readonlyProbe) {
          sourceIsReactiveArray = !!readonlyProbe.__v_isReactive
        }
      } else {
        sourceIsReactiveArray = !!source.__v_isReactive
      }
    }

    let needsWrap = sourceIsReactiveArray
    if (sourceIsReactiveArray) {
      let current: any = source
      while (current) {
        const nestedRaw = current.__v_raw
        if (nestedRaw) {
          current = nestedRaw
        } else {
          break
        }
      }
      if (current) {
        track(current, TrackOpTypes.ITERATE, ARRAY_ITERATE_KEY)
        source = current
      }
    }

    const listLength = source.length
    ret = new Array(listLength)
    for (let i = 0, l = listLength; i < l; i++) {
      const cachedNode = cached && cached[i]
      const item = source[i]
      if (needsWrap) {
        if (item !== null) {
          if (typeof item === 'object') {
            ret[i] = renderItem(
              reactive(item),
              i,
              undefined,
              cachedNode,
            )
          } else {
            ret[i] = renderItem(item, i, undefined, cachedNode)
          }
        } else {
          ret[i] = renderItem(item, i, undefined, cachedNode)
        }
      } else {
        ret[i] = renderItem(item, i, undefined, cachedNode)
      }
    }
  } else if (sourceIsString) {
    const chars = source as string
    const charCount = chars.length
    ret = new Array(charCount)
    for (let i = 0, l = charCount; i < l; i++) {
      const cachedNode = cached && cached[i]
      ret[i] = renderItem(chars[i], i, undefined, cachedNode)
    }
  } else if (sourceIsNumber) {
    if (__DEV__) {
      if (!Number.isInteger(source)) {
        warn(
          `The v-for range expect an integer value but got ${source}.`,
        )
      }
    }
    const range = source
    ret = new Array(range)
    for (let i = 0; i < range; i++) {
      const cachedNode = cached && cached[i]
      ret[i] = renderItem(i + 1, i, undefined, cachedNode)
    }
  } else if (sourceIsObject) {
    const iteratorMethod = source[Symbol.iterator as any]
    if (iteratorMethod) {
      ret = []
      let i = 0
      const iterator = iteratorMethod.call(source)
      let step = iterator.next()
      while (!step.done) {
        const cachedNode = cached && cached[i]
        ret.push(
          renderItem(step.value, i, undefined, cachedNode),
        )
        i++
        step = iterator.next()
      }
    } else if (sourceIsWeakMap || sourceIsWeakSet) {
      ret = []
    } else {
      const keys = Object.keys(source)
      ret = new Array(keys.length)
      for (let i = 0, l = keys.length; i < l; i++) {
        const key = keys[i]
        const cachedNode = cached && cached[i]
        ret[i] = renderItem(source[key], key, i, cachedNode)
      }
    }
  } else {
    ret = []
  }

  if (cache) {
    cache[index!] = ret
  }
  return ret
}

